```
135     request.on('response', function (response) {
136         if (response.headers.connection === 'close' &&
137             response.statusCode >= 300) {
138             var err3 = exports.statusCodeError(response.statusCode);
139             err3.response = response;
140             return callback(err3, data, response);
141         }
