Oh yea. Actionable, though. A more performant way would be to:
a. sort all responses by docId
b. iterate over all responses once and at once, generating the intersection.

_warning, ugly code incoming_:

```
const getIntersection = (responses) => {
  // sort all responses by id
  responses = responses.map(response => response.sort((a,b) => (a.id > b.id) ? 1 : ((b.id > a.id) ? -1 : 0)));

  const intersection = [],
        ids = {};

  const indexes = Array(responses.length).fill(0);

  // helpers
  const getLowestIdIndex = values => {
    let min = values[0].id,
        minIdx = 0;
    values.forEach((value, index) => {
      if (value && value.id < min) {
        min = value.id;
        minIdx = index;
      }
    });

    return minIdx;
  };

  while (indexes.every((idx, arrIndex) => idx < responses[arrIndex].length)) {
    const values = indexes.map((idx, arrIndex) => responses[arrIndex][idx]);
    // if all responses have this ID
    if (_.uniq(values, 'id').length === 1) {
      const row = values.pop();
      if (!ids[row.id]) {
        // only push to the intersection if it doesn't have this ID yet
        values.forEach(value => {
          if ('sort' in value) {
            row.sort = value.sort + ' ' + (row.sort || row.value);
          }
        });
        intersection.push(row);
        ids[row.id] = 1;
      }

      // increases all indexes
      indexes.forEach((idx, i) => indexes[i]++);
      continue;
    }

    // only increase the lowest index
    indexes[getLowestIdIndex(values)]++;
  }

  return intersection;
};
```

